		{"podman is not offered", "podman"},
		{"not offered", "are not offered"},
		{"no container running", "With no running container, only this machine is offered"},
		{"the engine is only read", "ps, info, inspect"},
		{"nothing is started", "starts nothing"},
		{"a remote engine is not detected", "is not detected as remote"},
		{"a remote engine still traces from here", "the trace still leaves from this machine"},
	}
	for _, tc := range cases {
		if !strings.Contains(body, tc.want) {
			t.Errorf("Path help lacks %q (%s)", tc.want, tc.what)
		}
	}
}","merged_ranks":[3,5]},{"rank":4,"score":47.8865,"file_path":"internal/ui/netdiag/path_source_flow_test.go","start_line":709,"end_line":728,"focus_line":723,"snippet_start_line":711,"snippet_end_line":728,"symbol_start_line":711,"symbol_end_line":728,"language":"Go","kind":"function","symbol_id":"local/devdesk:Go:internal/ui/netdiag/path_source_flow_test.go:function:TestPathSourceKeyIsInTheHelp","symbol_name":"TestPathSourceKeyIsInTheHelp","qualified_name":"TestPathSourceKeyIsInTheHelp","signature":"func TestPathSourceKeyIsInTheHelp(t *testing.T)","signals":["path","body","symbol-name","constraint:entity","constraint:phrase","constraint:relationship","exact-code-token","complete-symbol"],"snippet":"func TestPathSourceKeyIsInTheHelp(t *testing.T) {
